const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const {withEngine, terminal} = require('./helpers/download-resilience-fixture.cjs');

// These replay persisted checkpoints generated by a completed download; they are not process-kill tests.
for (const mode of ['local', 'remote']) {
  for (const phase of ['prepared', 'published']) {
    for (const known of [true, false]) {
      test(`${mode}: ${phase} checkpoint retains ${known ? 'verified' : 'unverified'} owned output`, async t => {
        let requests = 0;
        const f = await withEngine(t, mode, {file:{size:known ? 4 : null}, bytes:'data', onBytes:()=>{requests++;}});
        await f.client.execute('downloadFile',['1',{deleteAfterDownload:false}]);
        const before = await terminal(f.client);
        assert.equal(before.status, known ? 'completed' : 'unverified');
        await f.restart(async()=>{
          const statePath=path.join(f.dir,'state','engine.json');
          const state=JSON.parse(await fs.readFile(statePath,'utf8'));
          const record=state.recovery[before.id];
          record.finalization.phase=phase;
          record.cleanup={phase:'not-started',step:'file'};
          state.jobs[0].deleteAfterDownload=true;
          state.descriptions[before.id].cleanup=true;
          state.jobs[0].status='interrupted';
          if (phase === 'prepared') await fs.link(path.join(f.root,'file.bin'),path.join(f.root,record.partial));
          await fs.writeFile(statePath,JSON.stringify(state));
        });
        await f.client.execute('pause'); await f.client.execute('resume');
        const jobs=(await f.client.getSnapshot()).jobs;
        assert.equal(jobs.length,1); assert.equal(jobs[0].id,before.id);
        assert.equal(jobs[0].status,known ? 'completed' : 'unverified');
        assert.equal(jobs[0].verification,known ? 'verified' : 'unverified');
        assert.equal(await fs.readFile(path.join(f.root,'file.bin'),'utf8'),'data');
        assert.equal(requests,1); assert.deepEqual(f.deleted,[]);
      });
    }
  }
  for (const variant of ['missing', 'foreign identical bytes', 'directory', 'junction', 'invalid description', 'invalid root']) {
    test(`${mode}: saved publication with ${variant} requires attention without replay`, async t => {
      let requests=0;
      const f=await withEngine(t,mode,{file:{size:4},bytes:'data',onBytes:()=>{requests++;}});
      await f.client.execute('downloadFile',['1',{deleteAfterDownload:false}]);
      const before=await terminal(f.client); assert.equal(before.status,'completed');
      const dest=path.join(f.root,'file.bin');
      const foreign=path.join(f.dir,'foreign');
      await f.restart(async()=>{
        const statePath=path.join(f.dir,'state','engine.json');
        const state=JSON.parse(await fs.readFile(statePath,'utf8'));
        if (variant === 'invalid description') state.descriptions[before.id].file.id='999';
        else if (variant === 'invalid root') state.descriptions[before.id].root=path.join(f.dir,'outside');
        else {
          await fs.rename(dest,path.join(f.dir,'original'));
          if (variant === 'foreign identical bytes') await fs.writeFile(dest,'data');
          if (variant === 'directory') { await fs.mkdir(dest); await fs.writeFile(path.join(dest,'sentinel'),'foreign'); }
          if (variant === 'junction') { await fs.mkdir(foreign); await fs.writeFile(path.join(foreign,'sentinel'),'foreign'); await fs.symlink(foreign,dest,'junction'); }
        }
        await fs.writeFile(statePath,JSON.stringify(state));
      });
      const jobs=(await f.client.getSnapshot()).jobs;
      assert.equal(jobs.length,1); assert.equal(jobs[0].id,before.id); assert.equal(jobs[0].status,'needs-attention');
      if (variant === 'foreign identical bytes') assert.equal(await fs.readFile(dest,'utf8'),'data');
      if (variant === 'directory') assert.equal(await fs.readFile(path.join(dest,'sentinel'),'utf8'),'foreign');
      if (variant === 'junction') assert.equal(await fs.readFile(path.join(foreign,'sentinel'),'utf8'),'foreign');
      if (variant === 'missing') await assert.rejects(fs.lstat(dest),{code:'ENOENT'});
      if (variant.startsWith('invalid')) assert.equal(await fs.readFile(dest,'utf8'),'data');
      assert.equal(requests,1); assert.deepEqual(f.deleted,[]);
    });
  }
}
for (const mode of ['local', 'remote']) test(`${mode}: replaced root junction cannot adopt foreign publication`, async t => {
  let requests=0;
  const f=await withEngine(t,mode,{file:{size:4},bytes:'data',onBytes:()=>{requests++;}});
  await f.client.execute('downloadFile',['1',{deleteAfterDownload:false}]);
  const before=await terminal(f.client); assert.equal(before.status,'completed');
  const foreign=path.join(f.dir,'foreign-root');
  await f.restart(async()=>{
    await fs.rename(f.root,path.join(f.dir,'original-root'));
    await fs.mkdir(foreign); await fs.writeFile(path.join(foreign,'file.bin'),'data');
    await fs.symlink(foreign,f.root,'junction');
  });
  const jobs=(await f.client.getSnapshot()).jobs;
  assert.equal(jobs.length,1); assert.equal(jobs[0].id,before.id); assert.equal(jobs[0].status,'needs-attention');
  assert.equal(await fs.readFile(path.join(foreign,'file.bin'),'utf8'),'data');
  assert.equal(await fs.readFile(path.join(f.dir,'original-root','file.bin'),'utf8'),'data');
  assert.equal(requests,1); assert.deepEqual(f.deleted,[]);
});
